        elif isinstance(obj, list):
            res = []
            for item in obj:
                if item is None:
                    continue
                pi = process(item)
                if pi is not None:
                    res.append(pi)
            return res
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    processed_data = process(data)

    def get_values(obj, vals):
        if isinstance(obj, dict):
            for v in obj.values():
                get_values(v, vals)
        elif isinstance(obj, list):
            for i in obj:
                get_values(i, vals)
        else:
            vals.append(obj)

    values_list = []
    get_values(processed_data, values_list)
    value_counts = Counter(values_list)

    return {"data": processed_data, "value_counts": value_counts}
